    pub fn importBuffer(self: RenderService, name: [:0]const u8, buffer: c.ke_gpu_buffer, size: u64) Error!c.ke_component_id {
        var written: c.ke_component_id = undefined;
        try checkResult(self.ptr.import_buffer.?(self.ptr, name.ptr, buffer, size, &written));
        return written;
    }

    pub fn cid(self: RenderService, name: [:0]const u8) c.ke_component_id {
        return self.ptr.cid.?(self.ptr, name.ptr);
    }

    /// Opens a pass's recording context, from inside a render system's body.
    pub fn beginPass(self: RenderService, io: ?*const c.ke_render_pass_io) ?*abi_render_contract.c.ke_render_pass_ctx {
        return self.ptr.begin_pass.?(self.ptr, io);
    }

    /// Closes a recording context opened by begin_pass.
    pub fn endPass(self: RenderService, ctx: ?*abi_render_contract.c.ke_render_pass_ctx) void {
        return self.ptr.end_pass.?(self.ptr, ctx);
    }

    /// Acquires the service's render target as the backbuffer (a built-in resource named
    /// "backbuffer"), clears the per-pass command slot table, and clears the frame's color and
    /// depth. When the target has nothing to draw into this frame it succeeds without beginning one,
    /// and begin_pass then opens no pass; it fails with the target's code when acquiring failed.
    pub fn beginFrame(self: RenderService) Error!void {
        try checkResult(self.ptr.begin_frame.?(self.ptr));
    }

    /// Submits the passes outside the chain in the order they ended, then the chain in its order,
    /// then draws the frame's color into the backbuffer and presents the render target. A link whose
    /// pass recorded nothing still carries the color through it. Succeeds doing nothing when no
    /// frame began, and fails with the target's code when presenting failed.
    pub fn endFrame(self: RenderService) Error!void {
        try checkResult(self.ptr.end_frame.?(self.ptr));
    }

    /// Uploads interleaved vertices and 16-bit indices to device buffers.
    pub fn uploadMesh(self: RenderService, key: [:0]const u8, vertices: []const abi_mesh.c.ke_mesh_vertex, indices: []const u16) Error!abi_render_handles.c.ke_mesh_handle {
        var written: abi_render_handles.c.ke_mesh_handle = undefined;
        try checkResult(self.ptr.upload_mesh.?(self.ptr, key.ptr, vertices.ptr, @intCast(vertices.len), indices.ptr, @intCast(indices.len), &written));
        return written;
    }

    /// Resolves a mesh handle to its GPU buffers. Returns false for a handle this service never
    /// uploaded.
    pub fn meshBuffers(self: RenderService, h: abi_render_handles.c.ke_mesh_handle, out_vbo: ?*c.ke_gpu_buffer, out_ibo: ?*c.ke_gpu_buffer, out_index_count: ?*u32) bool {
        return self.ptr.mesh_buffers.?(self.ptr, h, out_vbo, out_ibo, out_index_count);
    }

    /// The color a pass clears its color attachments to (begin_render LOAD_OP_CLEAR).
    pub fn setClearColor(self: RenderService, r: f32, g: f32, b: f32, a: f32) void {
        return self.ptr.set_clear_color.?(self.ptr, r, g, b, a);
    }

    pub fn uploadTexture(self: RenderService, key: [:0]const u8, width: u32, height: u32, rgba: []const u8) Error!abi_render_handles.c.ke_texture_handle {
        var written: abi_render_handles.c.ke_texture_handle = undefined;
        try checkResult(self.ptr.upload_texture.?(self.ptr, key.ptr, width, height, rgba.ptr, @intCast(rgba.len), &written));
        return written;
    }

    pub fn createMaterial(self: RenderService, key: [:0]const u8, base_color: ?*const f32, metallic: f32, roughness: f32, albedo: abi_render_handles.c.ke_texture_handle, normal: abi_render_handles.c.ke_texture_handle, alpha_mode: abi_render_handles.c.ke_alpha_mode, alpha_cutoff: f32, ior: f32, distortion_strength: f32, shader: [:0]const u8) Error!abi_render_handles.c.ke_material_handle {
        var written: abi_render_handles.c.ke_material_handle = undefined;
        try checkResult(self.ptr.create_material.?(self.ptr, key.ptr, base_color, metallic, roughness, albedo, normal, alpha_mode, alpha_cutoff, ior, distortion_strength, shader.ptr, &written));
        return written;
    }

    /// What the service's resource binder holds for a material handle, the argument a pass gives its
    /// bind_material; an unknown handle resolves to the built-in white material.
    pub fn materialBinding(self: RenderService, h: abi_render_handles.c.ke_material_handle) c.ke_render_material_binding {
        return self.ptr.material_binding.?(self.ptr, h);
    }

    /// The pass bucket for a material handle, resolved from CPU-side storage — no GPU state touched.
    pub fn materialAlphaMode(self: RenderService, h: abi_render_handles.c.ke_material_handle) abi_render_handles.c.ke_alpha_mode {
        return self.ptr.material_alpha_mode.?(self.ptr, h);
    }

    /// The MASK discard threshold for a material handle.
    pub fn materialAlphaCutoff(self: RenderService, h: abi_render_handles.c.ke_material_handle) f32 {
        return self.ptr.material_alpha_cutoff.?(self.ptr, h);
    }

    pub fn uploadCubemap(self: RenderService, key: [:0]const u8, face_size: u32, faces: []const u8) Error!abi_render_handles.c.ke_texture_handle {
        var written: abi_render_handles.c.ke_texture_handle = undefined;
        try checkResult(self.ptr.upload_cubemap.?(self.ptr, key.ptr, face_size, faces.ptr, @intCast(faces.len), &written));
        return written;
    }

    /// The GPU view for a texture/cubemap handle.
    pub fn textureView(self: RenderService, h: abi_render_handles.c.ke_texture_handle) c.ke_gpu_texture_view {
        return self.ptr.texture_view.?(self.ptr, h);
    }

    /// The GPU view of a declared transient resource, by name.
    pub fn resourceView(self: RenderService, name: [:0]const u8) c.ke_gpu_texture_view {
        return self.ptr.resource_view.?(self.ptr, name.ptr);
    }

    /// The raw GPU texture behind a declared resource, for the copy operations that take a texture
    /// rather than a view.
    pub fn resourceTexture(self: RenderService, name: [:0]const u8) c.ke_gpu_texture {
        return self.ptr.resource_texture.?(self.ptr, name.ptr);
    }

    /// The GPU buffer published under `name` via import_buffer.
    pub fn resourceBuffer(self: RenderService, name: [:0]const u8) c.ke_gpu_buffer {
        return self.ptr.resource_buffer.?(self.ptr, name.ptr);
    }

    /// The size (bytes) of the buffer published under `name`.
    pub fn resourceBufferSize(self: RenderService, name: [:0]const u8) u64 {
        return self.ptr.resource_buffer_size.?(self.ptr, name.ptr);
    }

    /// The backbuffer's pixel size, callable from any phase. Refreshed once per frame at
    /// begin_frame, so a caller earlier in the tick reads the previous frame's size.
    pub fn backbufferSize(self: RenderService, out_w: ?*u32, out_h: ?*u32) void {
        return self.ptr.backbuffer_size.?(self.ptr, out_w, out_h);
    }

    /// Records a buffer upload to be flushed single-threaded at end_frame (before submit).
    pub fn upload(self: RenderService, buffer: c.ke_gpu_buffer, offset: u64, data: ?*const anyopaque, size: usize) void {
        return self.ptr.upload.?(self.ptr, buffer, offset, data, size);
    }

    /// Returns the pipeline for this exact params state, compiling it on first request.
    pub fn getOrCreatePipeline(self: RenderService, params: ?*const abi_render_gpu.c.ke_gpu_render_pipeline_params) c.ke_gpu_pipeline {
        return self.ptr.get_or_create_pipeline.?(self.ptr, params);
    }

    /// The authored-material shader name a material handle was created with (see create_material's
    /// `shader`).
    pub fn materialShader(self: RenderService, h: abi_render_handles.c.ke_material_handle) ?[*:0]const u8 {
        return self.ptr.material_shader.?(self.ptr, h);
    }

    /// Adds a reference to a mesh, keeping it resident.
    pub fn retainMesh(self: RenderService, h: abi_render_handles.c.ke_mesh_handle) void {
        return self.ptr.retain_mesh.?(self.ptr, h);
    }

    /// Drops a reference to a mesh, freeing it at zero.
    pub fn releaseMesh(self: RenderService, h: abi_render_handles.c.ke_mesh_handle) void {
        return self.ptr.release_mesh.?(self.ptr, h);
    }

    /// Adds a reference to a texture, keeping it resident.
    pub fn retainTexture(self: RenderService, h: abi_render_handles.c.ke_texture_handle) void {
        return self.ptr.retain_texture.?(self.ptr, h);
    }

    /// Drops a reference to a texture, freeing it at zero.
    pub fn releaseTexture(self: RenderService, h: abi_render_handles.c.ke_texture_handle) void {
        return self.ptr.release_texture.?(self.ptr, h);
    }

    /// Adds a reference to a material, keeping it resident.
    pub fn retainMaterial(self: RenderService, h: abi_render_handles.c.ke_material_handle) void {
        return self.ptr.retain_material.?(self.ptr, h);
    }

    /// Drops a reference to a material, freeing it at zero.
    pub fn releaseMaterial(self: RenderService, h: abi_render_handles.c.ke_material_handle) void {
        return self.ptr.release_material.?(self.ptr, h);
    }

    /// Path-keyed probe for a resident mesh upload: on a hit, retains and writes the resident handle
    /// to `out`. try_get_texture also serves cubemaps (shared cache).
    pub fn tryGetMesh(self: RenderService, key: [:0]const u8, out: ?*abi_render_handles.c.ke_mesh_handle) bool {
        return self.ptr.try_get_mesh.?(self.ptr, key.ptr, out);
    }

    /// Path-keyed probe for a resident texture upload.
    pub fn tryGetTexture(self: RenderService, key: [:0]const u8, out: ?*abi_render_handles.c.ke_texture_handle) bool {
        return self.ptr.try_get_texture.?(self.ptr, key.ptr, out);
    }

    /// Path-keyed probe for a resident material.
    pub fn tryGetMaterial(self: RenderService, key: [:0]const u8, out: ?*abi_render_handles.c.ke_material_handle) bool {
        return self.ptr.try_get_material.?(self.ptr, key.ptr, out);
    }

    /// The built-in 1×1 white texture, resolvable everywhere a neutral albedo is wanted.
    pub fn whiteTexture(self: RenderService) abi_render_handles.c.ke_texture_handle {
        return self.ptr.white_texture.?(self.ptr);
    }

    /// Resolves a shader by logical NAME + STAGE to a device-ready module.
    pub fn loadShader(self: RenderService, name: [:0]const u8, stage: c.ke_gpu_shader_stage) Error!c.ke_gpu_shader_module {
        var written: c.ke_gpu_shader_module = undefined;
        try checkResult(self.ptr.load_shader.?(self.ptr, name.ptr, stage, &written));
        return written;
    }

    /// Replaces the frame globals and records their upload; a shader reads them as `ke_frame`.
    pub fn setFrameGlobals(self: RenderService, globals: ?*const c.ke_render_frame_globals) void {
        return self.ptr.set_frame_globals.?(self.ptr, globals);
    }

    /// The frame globals last set, zero before the first.
    pub fn frameGlobals(self: RenderService) ?*const c.ke_render_frame_globals {
        return self.ptr.frame_globals.?(self.ptr);
    }

    /// Replaces the scene's light and records its upload; a shader reads it as `ke_lighting`.
    pub fn setLighting(self: RenderService, lighting_: ?*const c.ke_render_lighting) void {
        return self.ptr.set_lighting.?(self.ptr, lighting_);
    }

    /// The scene's light last set, zero before the first.
    pub fn lighting(self: RenderService) ?*const c.ke_render_lighting {
        return self.ptr.lighting.?(self.ptr);
    }

    /// The resource binder the service was created with, through which a pass brings its resources
    /// to its shaders; the service has given it `ke_frame`, `ke_lighting` and the `ke_samp_*`
    /// samplers.
    pub fn resourceBinder(self: RenderService) ?*abi_render_gpu.c.ke_render_resource_binder {
        return self.ptr.resource_binder.?(self.ptr);
    }

    /// Texel format of the backbuffer, the format a pipeline drawing into it declares.
    pub fn backbufferFormat(self: RenderService) abi_render_gpu.c.ke_gpu_texture_format {
        return self.ptr.backbuffer_format.?(self.ptr);
    }

    /// Texel format of the named texture resource, the format a pipeline drawing into it declares;
    /// KE_GPU_TEXTURE_FORMAT_INVALID for an unknown name or a resource without one.
    pub fn resourceFormat(self: RenderService, name: [:0]const u8) abi_render_gpu.c.ke_gpu_texture_format {
        return self.ptr.resource_format.?(self.ptr, name.ptr);
    }

    /// Counts the times the targets declared relative to the backbuffer were recreated, which
    /// `begin_frame` does when the backbuffer changes size. A pass that keeps something made from a
    /// declared target's view, a bind group for instance, rebuilds it when the count changes.
    pub fn resourceGeneration(self: RenderService) u32 {
        return self.ptr.resource_generation.?(self.ptr);
    }

    /// Gives a pass a place in the chain, after every pass that joined the same stage before it. The
    /// place is kept until leave_chain.
    pub fn joinChain(self: RenderService, stage: RenderStage, mode: RenderChainMode) Error!c.ke_render_chain_link {
        var written: c.ke_render_chain_link = undefined;
        try checkResult(self.ptr.join_chain.?(self.ptr, @intFromEnum(stage), @intFromEnum(mode), &written));
        return written;
    }

    /// Gives the place back. An unknown link is ignored.
    pub fn leaveChain(self: RenderService, link: c.ke_render_chain_link) void {
        return self.ptr.leave_chain.?(self.ptr, link);
    }

    /// Texel format of the color a pass of stage draws into, the format its pipeline declares.
    pub fn chainFormat(self: RenderService, stage: RenderStage) abi_render_gpu.c.ke_gpu_texture_format {
        return self.ptr.chain_format.?(self.ptr, @intFromEnum(stage));
    }

};

pub const RenderCamera = struct {
    ptr: *c.ke_render_camera,
    owner: ?c.ke_render_camera_handle = null,

    pub fn deinit(self: RenderCamera) void {
        if (self.owner) |owner| owner.destroy.?(owner.ref);
    }

    /// The vtable whose slots call the methods of T, which embeds it as the named field.
    pub fn implement(comptime T: type, comptime field: []const u8) c.ke_render_camera {
        return .{
            .view = &struct {
                fn call(self: ?*c.ke_render_camera, a0: ?*const abi_math.c.ke_mat4, a1: ?*abi_math.c.ke_mat4) callconv(.c) void {
                    const state: *T = @alignCast(@fieldParentPtr(field, self orelse return));
                    return T.view(state, a0, a1);
                }
            }.call,
            .view_rotation = &struct {
                fn call(self: ?*c.ke_render_camera, a0: ?*const abi_math.c.ke_mat4, a1: ?*abi_math.c.ke_mat4) callconv(.c) void {
                    const state: *T = @alignCast(@fieldParentPtr(field, self orelse return));
                    return T.viewRotation(state, a0, a1);
                }
            }.call,
            .projection = &struct {
                fn call(self: ?*c.ke_render_camera, a0: ?*const abi_render_components.c.ke_camera_component, a1: f32, a2: ?*abi_math.c.ke_mat4) callconv(.c) void {
                    const state: *T = @alignCast(@fieldParentPtr(field, self orelse return));
                    return T.projection(state, a0, a1, a2);
                }
            }.call,
            .perspective_projection = &struct {
                fn call(self: ?*c.ke_render_camera, a0: ?*const abi_render_components.c.ke_camera_component, a1: f32, a2: ?*abi_math.c.ke_mat4) callconv(.c) void {
                    const state: *T = @alignCast(@fieldParentPtr(field, self orelse return));
                    return T.perspectiveProjection(state, a0, a1, a2);
                }
            }.call,
            .perspective_frustum = &struct {
                fn call(self: ?*c.ke_render_camera, a0: ?*const abi_render_components.c.ke_camera_component, a1: f32, a2: ?*c.ke_camera_frustum) callconv(.c) void {
                    const state: *T = @alignCast(@fieldParentPtr(field, self orelse return));
                    return T.perspectiveFrustum(state, a0, a1, a2);
                }
            }.call,
        };
    }

    /// World-to-view for a camera placed by `camera_world`.
    pub fn view(self: RenderCamera, camera_world: ?*const abi_math.c.ke_mat4, out_view: ?*abi_math.c.ke_mat4) void {
        return self.ptr.view.?(self.ptr, camera_world, out_view);
    }

    /// The view matrix of `view` with its translation removed, leaving only the rotation.
    pub fn viewRotation(self: RenderCamera, camera_world: ?*const abi_math.c.ke_mat4, out_view: ?*abi_math.c.ke_mat4) void {
        return self.ptr.view_rotation.?(self.ptr, camera_world, out_view);
    }

    /// The projection the camera describes. `orthographic` picks the kind, `orthographic_size` is
    /// half the visible height, and `fov` is the vertical field of view in degrees.
    pub fn projection(self: RenderCamera, camera: ?*const abi_render_components.c.ke_camera_component, aspect: f32, out_proj: ?*abi_math.c.ke_mat4) void {
        return self.ptr.projection.?(self.ptr, camera, aspect, out_proj);
    }

    /// A perspective projection from the camera's field of view, whatever its `orthographic` flag
    /// says.
    pub fn perspectiveProjection(self: RenderCamera, camera: ?*const abi_render_components.c.ke_camera_component, aspect: f32, out_proj: ?*abi_math.c.ke_mat4) void {
        return self.ptr.perspective_projection.?(self.ptr, camera, aspect, out_proj);
    }

    /// The perspective frustum the camera's field of view describes, whatever its `orthographic`
    /// flag says.
    pub fn perspectiveFrustum(self: RenderCamera, camera: ?*const abi_render_components.c.ke_camera_component, aspect: f32, out_frustum: ?*c.ke_camera_frustum) void {
        return self.ptr.perspective_frustum.?(self.ptr, camera, aspect, out_frustum);
    }

};

pub const RenderFrame = struct {
    ptr: *c.ke_render_frame,
    owner: ?c.ke_render_frame_handle = null,

    pub fn deinit(self: RenderFrame) void {
        if (self.owner) |owner| owner.destroy.?(owner.ref);
    }

    /// The vtable whose slots call the methods of T, which embeds it as the named field.
    pub fn implement(comptime T: type, comptime field: []const u8) c.ke_render_frame {
        return .{
            .frame_cid = &struct {
                fn call(self: ?*c.ke_render_frame) callconv(.c) c.ke_component_id {
                    const state: *T = @alignCast(@fieldParentPtr(field, self orelse return std.mem.zeroes(c.ke_component_id)));
                    return T.frameCid(state);
                }
            }.call,
        };
    }

    /// The tag the system that begins the frame writes and the system that ends it reads. A pass
    /// that reads it runs inside the frame.
    pub fn frameCid(self: RenderFrame) c.ke_component_id {
        return self.ptr.frame_cid.?(self.ptr);
    }

};

